      "code": "def solve(s, t):\n    mode = 'anagrams'\n    if len(t) == 0:\n        return (True if (mode == 'permutation') else [])\n    a = list(s)\n    need = {}\n    result = []\n    for c in t:\n        need[c] = ((need.get(c, 0) or 0) + 1)\n    left = 0\n    missing = len(t)\n    right = 0\n    while (right < len(a)):\n        c = a[right]\n        if (c in need):\n            if (need.get(c, 0) > 0):\n                missing -= 1\n            need[c] = (need.get(c, 0) - 1)\n        if (((right - left) + 1) > len(t)):\n            outgoing = a[left]\n            left += 1\n            if (outgoing in need):\n                need[outgoing] = (need.get(outgoing, 0) + 1)\n                if (need.get(outgoing, 0) > 0):\n                    missing += 1\n        if ((((right - left) + 1) == len(t)) and (missing == 0)):\n            result.append(left)\n            if (mode == 'permutation'):\n                return True\n        right += 1\n    return (False if (mode == 'permutation') else result)",
