      "code": "def solve(a, k):\n    next = [i + 1 if i + 1 < len(a) else -1 for i in range(len(a))]\n    head = (0 if len(a) > 0 else (-1))\n    if (len(a) < 2):\n        return a\n    tail = head\n    length = 1\n    while (next[tail] != (-1)):\n        tail = next[tail]\n        length += 1\n    shift = (k % length)\n    if (shift == 0):\n        return a\n    next[tail] = head\n    newTail = head\n    step = 0\n    while (step < ((length - shift) - 1)):\n        newTail = next[newTail]\n        step += 1\n    head = next[newTail]\n    next[newTail] = (-1)\n    result = []\n    node = head\n    while (node != (-1)):\n        result.append(a[node])\n        node = next[node]\n    return result",
